from typing import List
from wordle.types import GuessResult, Feedback

RESET_COLOR = "\033[0m"
HIT_COLOR = "\033[92m"  # Green
PRESENT_COLOR = "\033[93m"  # Yellow
MISS_COLOR = "\033[90m"  # Grey


def render_board(results: List[GuessResult]) -> str:
    """Render the entire game board with all guesses."""
    board = ""
    for result in results:
        board += render_guess(result) + "\n"
    # Add empty rows for unused attempts
    board += render_empty_row() * (6 - len(results))
    return board


def render_guess(result: GuessResult) -> str:
    """Render a single guess result as a colored row."""
    colored_guess = "".join(_colorize_letter(letter, feedback) for letter, feedback in zip(result.guess, result.feedbacks))
    return colored_guess


def render_empty_row() -> str:
    """Render an empty row for unused attempts."""
    return " " * 5  # Assuming 5-letter words


def _colorize_letter(letter: str, feedback_type: str) -> str:
    """Apply color formatting to a letter based on feedback."""
    if feedback_type == "hit":
        return f"{HIT_COLOR}{letter}{RESET_COLOR}"
    elif feedback_type == "present":
        return f"{PRESENT_COLOR}{letter}{RESET_COLOR}"
    else:
        return f"{MISS_COLOR}{letter}{RESET_COLOR}"


def render_keyboard(used_letters: dict[str, str]) -> str:
    """Render a keyboard showing letter status."""
    keyboard = ""
    for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        if letter in used_letters:
            if used_letters[letter] == "hit":
                keyboard += f"{HIT_COLOR}{letter}{RESET_COLOR} "
            elif used_letters[letter] == "present":
                keyboard += f"{PRESENT_COLOR}{letter}{RESET_COLOR} "
            else:
                keyboard += f"{MISS_COLOR}{letter}{RESET_COLOR} "
        else:
            keyboard += letter + " "
    return keyboard


